export function offlineCases(sr=48000){const rows=[];for(const frame of[3180544,3416064,3796736])for(const [lane,offset]of[[0,0],[1,.25],[2,.75]])rows.push({label:`late-${frame}+${offset}`,lane,integerFrame:frame,offset,time:(frame+offset)/sr});for(const frame of[3180544,3416064,3796736]){rows.push({label:`late-${frame}-previous-double`,lane:3,integerFrame:frame,offset:'previous-double',time:adjacent(frame/sr,-1)});let control;for(let f=frame+2048;f<frame+4096;f++){const d=timeDetails(f/sr,sr);if(d.productFraction===0&&d.exactOffsetFromRoundedFrame>0){control={label:`late-${f}-zero-product-after-exact`,lane:3,integerFrame:f,offset:0,time:f/sr};break;}}if(!control)throw Error('Discriminating late fixture missing');rows.push(control);}for(const[frame,offset]of[[48000,0],[96000,.25],[144000,.75]])rows.push({label:`early-${frame}+${offset}`,lane:0,integerFrame:frame,offset,time:(frame+offset)/sr});return rows.map(row=>({...row,request:timeDetails(row.time,sr)}));}
