const recorderSource=`class BoundaryCapture extends AudioWorkletProcessor{constructor(){super();this.pre=null;this.job=null;this.stop=false;this.port.onmessage=({data:m})=>{if(m.type==='stop'){this.stop=true;this.job=null;}if(m.type==='preflight')this.pre={rows:[],gaps:[],end:null};if(m.type==='capture'){if(this.job||m.frames<1||m.frames>sampleRate*4){this.port.postMessage({type:'error',error:'Capture bound violated'});return;}this.job={frames:m.frames,at:0,start:null,rows:[],channels:[new Float32Array(m.frames),new Float32Array(m.frames)]};}};}process(inputs,outputs){outputs[0].forEach(c=>c.fill(0));if(this.stop)return false;const size=outputs[0][0].length;if(this.pre){const p=this.pre;if(p.end!==null&&p.end!==currentFrame){p.gaps.push({expected:p.end,actual:currentFrame});p.rows=[];}p.rows.push({frame:currentFrame,size});p.end=currentFrame+size;if(p.rows.length===64){this.port.postMessage({type:'preflight',...p});this.pre=null;}}if(this.job){const j=this.job;if(j.start===null)j.start=currentFrame;j.rows.push({frame:currentFrame,size,inputChannels:inputs[0].length});const n=Math.min(size,j.frames-j.at);for(let c=0;c<2;c++)if(inputs[0][c])j.channels[c].set(inputs[0][c].subarray(0,n),j.at);j.at+=n;if(j.at===j.frames){this.port.postMessage({type:'capture',firstFrame:j.start,frames:j.frames,rows:j.rows,channels:j.channels},j.channels.map(c=>c.buffer));this.job=null;}}return true;}}registerProcessor('pause-boundary-capture',BoundaryCapture);`;
